import dataset from "@/data/ramsar-sites.json";

/**
 * India's Ramsar Sites, generated by scripts/build_geodata.py from the
 * project-supplied Ramsar Sites Information Service export. State and
 * district are derived by point-in-polygon against the supplied boundaries.
 */
export type RamsarSite = {
  id: number;
  name: string;
  designationDate: string;
  designationYear: number;
  lastPublicationDate: string | null;
  areaHa: number;
  latitude: number;
  longitude: number;
  state: string;
  district: string;
  stateOffsetKm: number;
  districtOffsetKm: number;
  administrativeRegion: string | null;
  wetlandTypes: Partial<Record<WetlandGroup, string[]>>;
  criteria: number[];
  elevationMaxM: number | null;
  elevationMinM: number | null;
  montreuxListed: string | null;
  managementPlanImplemented: string | null;
  managementPlanAvailable: string | null;
  ecosystemServices: string[];
  threats: string[];
  globalDesignations: string | null;
  nationalDesignation: string | null;
  summary: string[];
};

export type WetlandGroup = "Inland wetlands" | "Marine or coastal wetlands" | "Human-made wetlands";

export const WETLAND_GROUPS: WetlandGroup[] = [
  "Inland wetlands",
  "Marine or coastal wetlands",
  "Human-made wetlands",
];

/** Lean record sent to client components (map, tables). */
export type RamsarSitePoint = Pick<
  RamsarSite,
  "id" | "name" | "designationYear" | "areaHa" | "latitude" | "longitude" | "state" | "district"
> & { groups: WetlandGroup[] };

const sites = dataset.sites as RamsarSite[];

export const RAMSAR_SOURCE = dataset.source;

export function getRamsarSites(): RamsarSite[] {
  return sites;
}

export function getRamsarSite(id: number): RamsarSite | undefined {
  return sites.find((site) => site.id === id);
}

export function toSitePoint(site: RamsarSite): RamsarSitePoint {
  return {
    id: site.id,
    name: site.name,
    designationYear: site.designationYear,
    areaHa: site.areaHa,
    latitude: site.latitude,
    longitude: site.longitude,
    state: site.state,
    district: site.district,
    groups: WETLAND_GROUPS.filter((group) => group in site.wetlandTypes),
  };
}

export function getSitePoints(): RamsarSitePoint[] {
  return sites.map(toSitePoint);
}

/** Summary figures, all derived from the dataset above. */
export function getRamsarSummary() {
  const states = new Set(sites.map((s) => s.state));
  const totalAreaHa = sites.reduce((sum, s) => sum + s.areaHa, 0);
  const latest = [...sites].sort((a, b) => b.designationDate.localeCompare(a.designationDate))[0];
  const earliest = [...sites].sort((a, b) => a.designationDate.localeCompare(b.designationDate))[0];
  return {
    siteCount: sites.length,
    stateCount: states.size,
    totalAreaHa,
    latest,
    earliest,
  };
}
